package kz.alitulegenov.creditdecisionengine.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.util.UUID;

/**
 * Inbound HTTP request payload from the upstream Loan Origination System (LOS)
 * containing the borrower's financial/credit bureau profile and requested loan parameters.
 *
 * @param requestId                     unique idempotency key generated by the caller
 * @param applicantAgeYears             full age of the applicant in years (18–100)
 * @param monthlyIncome                 verified net monthly income in KZT (> 0)
 * @param existingMonthlyPayments       total monthly payments on existing loans in KZT (>= 0)
 * @param creditScore                   external credit bureau score (300–850 technical scale)
 * @param hasActiveDelinquency          whether the applicant currently has active overdue debt
 * @param maxDelinquencyDaysLast12Months maximum historical overdue days in the past 12 months (>= 0)
 * @param requestedAmount               requested loan principal in KZT (> 0)
 * @param requestedTermMonths           requested loan term in months (6–60)
 */
public record CreditDecisionRequest(
    @NotNull(message = "requestId is required")
    UUID requestId,

    @NotNull(message = "applicantAgeYears is required")
    @Min(value = 18, message = "applicantAgeYears must be at least 18")
    @Max(value = 100, message = "applicantAgeYears must be at most 100")
    Integer applicantAgeYears,

    @NotNull(message = "monthlyIncome is required")
    @DecimalMin(value = "0.01", message = "monthlyIncome must be greater than 0")
    @Digits(integer = 17, fraction = 2, message = "monthlyIncome must have at most 2 decimal places")
    BigDecimal monthlyIncome,

    @NotNull(message = "existingMonthlyPayments is required")
    @DecimalMin(value = "0.00", message = "existingMonthlyPayments must not be negative")
    @Digits(integer = 17, fraction = 2, message = "existingMonthlyPayments must have at most 2 decimal places")
    BigDecimal existingMonthlyPayments,

    @NotNull(message = "creditScore is required")
    @Min(value = 300, message = "creditScore must be between 300 and 850")
    @Max(value = 850, message = "creditScore must be between 300 and 850")
    Integer creditScore,

    @NotNull(message = "hasActiveDelinquency is required")
    Boolean hasActiveDelinquency,

    @NotNull(message = "maxDelinquencyDaysLast12Months is required")
    @Min(value = 0, message = "maxDelinquencyDaysLast12Months must not be negative")
    @Max(value = 3650, message = "maxDelinquencyDaysLast12Months is out of range")
    Integer maxDelinquencyDaysLast12Months,

    @NotNull(message = "requestedAmount is required")
    @DecimalMin(value = "0.01", message = "requestedAmount must be greater than 0")
    @Digits(integer = 17, fraction = 2, message = "requestedAmount must have at most 2 decimal places")
    BigDecimal requestedAmount,

    @NotNull(message = "requestedTermMonths is required")
    @Min(value = 6, message = "requestedTermMonths must be between 6 and 60")
    @Max(value = 60, message = "requestedTermMonths must be between 6 and 60")
    Integer requestedTermMonths
) {
}
